"""One packed allocation shared by separate, KV and QKV linear operations."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal, cast

import torch
from torch.nn import functional as F

type Arm = Literal["separate", "kv", "qkv"]
type Outputs = tuple[torch.Tensor, torch.Tensor, torch.Tensor]


def require_fp32(value: torch.Tensor) -> None:
    if (
        value.device.type != "cpu"
        or value.dtype != torch.float32
        or value.requires_grad
        or torch.is_autocast_enabled("cpu")
    ):
        raise ValueError("Projection requires CPU FP32 without gradients/autocast")


@dataclass(frozen=True)
class PackedQKV:
    weight: torch.Tensor
    query_width: int
    kv_width: int

    @classmethod
    def from_weights(
        cls, query: torch.Tensor, key: torch.Tensor, value: torch.Tensor
    ) -> PackedQKV:
        for item in (query, key, value):
            require_fp32(item)
            if item.ndim != 2 or not torch.isfinite(item).all().item():
                raise ValueError("Projection weights require finite matrices")
        if (
            key.shape != value.shape
            or query.shape[1] != key.shape[1]
            or query.shape[0] != 2 * key.shape[0]
            or min(key.shape) <= 0
        ):
            raise ValueError("Packing requires biasless Q16/KV8 width geometry")
        return cls(torch.cat((query, key, value)), query.shape[0], key.shape[0])

    @property
    def views(self) -> Outputs:
        return cast(
            Outputs,
            torch.split(self.weight, [self.query_width, self.kv_width, self.kv_width]),
        )

    def project(self, value: torch.Tensor, arm: Arm) -> Outputs:
        require_fp32(value)
        if value.ndim not in (2, 3) or value.shape[-1] != self.weight.shape[1]:
            raise ValueError("Projection input width/rank differs")
        if arm == "separate":
            query, key, values = self.views
            return F.linear(value, query), F.linear(value, key), F.linear(value, values)
        if arm == "kv":
            query = F.linear(value, self.views[0])
            key, values = torch.split(
                F.linear(value, self.weight[self.query_width :]), self.kv_width, dim=-1
            )
            return query, key, values
        if arm == "qkv":
            return cast(
                Outputs,
                torch.split(
                    F.linear(value, self.weight),
                    [self.query_width, self.kv_width, self.kv_width],
                    dim=-1,
                ),
            )
        raise ValueError("Unknown projection arm")


def quality(reference: Outputs, actual: Outputs) -> dict[str, object]:
    """Symmetric max tolerance; projection evidence is not full-model quality."""
    failures = 0
    maximum = 0.0
    relative = 0.0
    for expected, observed in zip(reference, actual, strict=True):
        require_fp32(expected)
        require_fp32(observed)
        if expected.shape != observed.shape:
            raise ValueError("Projection output geometry differs")
        # FP64 computes the gate without rounding its FP32 operands/tolerance.
        left, right = expected.double(), observed.double()
        error = (left - right).abs()
        scale = torch.maximum(left.abs(), right.abs())
        finite = torch.isfinite(left) & torch.isfinite(right)
        failures += int((~finite | (error > (scale * 1e-3).clamp_min(1e-3))).sum())
        if finite.all().item():
            maximum = max(maximum, float(error.max()))
            relative = max(relative, float((error / scale.clamp_min(1e-300)).max()))
        else:
            return {
                "passed": False,
                "finite": False,
                "failed_elements": failures,
                "max_absolute_error": None,
                "max_relative_error": None,
            }
    return {
        "passed": failures == 0,
        "finite": True,
        "failed_elements": failures,
        "max_absolute_error": maximum,
        "max_relative_error": relative,
        "atol": 1e-3,
        "rtol": 1e-3,
        "rule": "abs(a-b)<=max(atol,rtol*max(abs(a),abs(b)))",
    }

"""Projection algebra, exact shared storage and effect/failure boundaries."""

from __future__ import annotations

import json
from pathlib import Path
from typing import cast

import pytest
import torch
from hypothesis import given, settings
from hypothesis import strategies as st

from benchmarks.analysis.torch.prefix.production import study as original
from benchmarks.analysis.torch.projection import qkv, run, study


def weights(width: int) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    values = torch.arange(4 * width * width, dtype=torch.float32).reshape(
        4 * width, width
    )
    return (
        values[: 2 * width] / 100,
        values[2 * width : 3 * width] / 100,
        values[3 * width :] / 100,
    )


@settings(max_examples=12, deadline=None, derandomize=True)
@given(width=st.integers(2, 12), batch=st.integers(1, 3), length=st.integers(1, 11))
def test_packed_projection_matches_independent_linear(
    width: int, batch: int, length: int
) -> None:
    source = weights(width)
    packed = qkv.PackedQKV.from_weights(*source)
    value = torch.sin(
        torch.arange(batch * length * width, dtype=torch.float32)
    ).reshape(batch, length, width)
    baseline = cast(
        qkv.Outputs, tuple(torch.nn.functional.linear(value, w) for w in source)
    )
    pointer = packed.weight.untyped_storage().data_ptr()
    assert all(
        w.untyped_storage().data_ptr() == pointer and w.is_contiguous()
        for w in packed.views
    )
    assert all(torch.equal(a, b) for a, b in zip(source, packed.views, strict=True))
    for arm in ("separate", "kv", "qkv"):
        actual = packed.project(value, arm)
        assert qkv.quality(baseline, actual)["passed"] is True
        assert tuple(t.shape for t in actual) == (
            (batch, length, 2 * width),
            (batch, length, width),
            (batch, length, width),
        )
    assert packed.weight.numel() * 4 == sum(w.numel() * 4 for w in source)


def test_output_views_preserve_observed_stride_difference() -> None:
    packed = qkv.PackedQKV.from_weights(*weights(4))
    value = torch.ones(2, 3, 4)
    separate = packed.project(value, "separate")
    combined = packed.project(value, "qkv")
    assert separate[0].stride() == (24, 8, 1)
    assert combined[0].stride() == (48, 16, 1)
    assert (
        combined[0].untyped_storage().data_ptr()
        == combined[1].untyped_storage().data_ptr()
    )


@pytest.mark.parametrize("bad", ["dtype", "gradient", "width", "finite", "autocast"])
def test_unsupported_weights_fail_before_cat(
    monkeypatch: pytest.MonkeyPatch, bad: str
) -> None:
    source = list(weights(4))
    if bad == "dtype":
        source[0] = source[0].double()
    if bad == "gradient":
        source[0].requires_grad_(True)
    if bad == "width":
        source[0] = source[0][:-1]
    if bad == "finite":
        source[0][0, 0] = float("nan")

    def unexpected(*args: object, **kwargs: object) -> torch.Tensor:
        raise AssertionError("No packing allocation before admission")

    monkeypatch.setattr(torch, "cat", unexpected)
    if bad == "autocast":
        with torch.autocast("cpu", dtype=torch.bfloat16), pytest.raises(ValueError):
            qkv.PackedQKV.from_weights(*source)
        assert not torch.is_autocast_enabled("cpu")
    else:
        with pytest.raises(ValueError):
            qkv.PackedQKV.from_weights(*source)


def test_symmetric_max_gate_accepts_near_zero_and_rejects_drift() -> None:
    expected = (torch.tensor([0.0]),) * 3
    close = (torch.tensor([0.0009]),) * 3
    far = (torch.tensor([0.0011]),) * 3
    assert qkv.quality(expected, close)["passed"] is True
    assert qkv.quality(expected, far)["passed"] is False
    assert qkv.quality(expected, (torch.tensor([float("nan")]),) * 3)["finite"] is False


def test_launcher_uses_importable_module(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    import sys

    from benchmarks.analysis.torch import process

    captured: list[str] = []

    def launch(module: str, model: Path, output: Path, *, timeout: float) -> int:
        captured.append(module)
        assert timeout == 120
        return 0

    monkeypatch.setattr(process, "launch", launch)
    monkeypatch.setattr(run, "__name__", "__main__")
    monkeypatch.setattr(
        sys,
        "argv",
        ["projection.run", str(tmp_path), "--output", str(tmp_path / "run.json")],
    )
    with pytest.raises(SystemExit) as error:
        run.main()
    assert error.value.code == 0
    assert captured == ["benchmarks.analysis.torch.projection.run"]


class Frozen:
    def hashes(self) -> dict[str, str]:
        return {}

    def archive(self) -> dict[str, object]:
        return {}


def fake_setup(monkeypatch: pytest.MonkeyPatch) -> dict[str, int]:
    threads = {"value": 3}

    def set_threads(value: int) -> None:
        threads["value"] = value

    def get_threads() -> int:
        return threads["value"]

    def no_verify(files: object) -> None:
        pass

    def fake_operands(
        model: Path, rows: object, pad: int
    ) -> tuple[
        qkv.PackedQKV,
        list[tuple[str, torch.Tensor, dict[str, object]]],
        dict[str, object],
    ]:
        packed = qkv.PackedQKV.from_weights(*weights(4))
        return (
            packed,
            [(name, torch.ones(1, 2, 4), {}) for name, _ in study.PROFILES],
            {},
        )

    monkeypatch.setattr(torch, "set_num_threads", set_threads)
    monkeypatch.setattr(torch, "get_num_threads", get_threads)
    monkeypatch.setattr(study, "input_vectors", lambda: [])
    monkeypatch.setattr(study, "padding_id", lambda model: 151643)
    monkeypatch.setattr(study, "operands", fake_operands)
    monkeypatch.setattr(study, "freeze_sources", lambda paths, output: Frozen())
    monkeypatch.setattr(original, "verify_files", no_verify)
    monkeypatch.setattr(original, "verify_sources", no_verify)
    return threads


def test_fake_worker_retains_all_calls_and_restores(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    threads = fake_setup(monkeypatch)
    output = tmp_path / "primitive.json"
    assert study.study(tmp_path, output)
    result = json.loads(output.read_text())
    assert (
        result["completed"] and result["quality_passed"] and result["accepted"] is False
    )
    assert sum(len(entry["calls"]) for entry in result["operands"]) == 96
    assert all(entry["pending_calls"] == 0 for entry in result["operands"])
    assert result["threads_restored"] and threads["value"] == 3
    for entry in result["operands"]:
        assert Path(entry["raw_tensors"]).exists()


def test_quality_exception_retains_produced_output(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    threads = fake_setup(monkeypatch)

    def fail(reference: qkv.Outputs, actual: qkv.Outputs) -> dict[str, object]:
        raise RuntimeError("gate failed after output")

    monkeypatch.setattr(study, "quality", fail)
    output = tmp_path / "failed.json"
    with pytest.raises(RuntimeError):
        study.study(tmp_path, output)
    result = json.loads(output.read_text())
    first = result["operands"][0]
    assert len(first["calls"]) == 1 and first["calls"][0]["quality"] is None
    assert Path(first["raw_tensors"]).exists()
    assert not result["completed"] and not result["quality_passed"]
    assert threads["value"] == 3 and first["pending_calls"] == 23


@pytest.mark.parametrize("boundary", ["restore", "final_save"])
def test_completion_failure_clears_selection(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path, boundary: str
) -> None:
    threads = fake_setup(monkeypatch)
    output = tmp_path / "completion-failed.json"
    if boundary == "restore":

        def set_threads(value: int) -> None:
            if value == 3:
                raise RuntimeError("restoration failed")
            threads["value"] = value

        monkeypatch.setattr(torch, "set_num_threads", set_threads)
    else:
        original_write = Path.write_text
        failed = False

        def write_text(
            path: Path,
            data: str,
            encoding: str | None = None,
            errors: str | None = None,
            newline: str | None = None,
        ) -> int:
            nonlocal failed
            if path == output and json.loads(data)["completed"] and not failed:
                failed = True
                raise OSError("final save failed")
            return original_write(
                path, data, encoding=encoding, errors=errors, newline=newline
            )

        monkeypatch.setattr(Path, "write_text", write_text)
    with pytest.raises((RuntimeError, OSError)):
        study.study(tmp_path, output)
    result = json.loads(output.read_text())
    assert not result["completed"] and not result["quality_passed"]
    assert result["primitive_eligible"] == {"kv": False, "qkv": False}
    assert sum(len(entry["calls"]) for entry in result["operands"]) == 96


def test_parent_sidecars_survive_worker(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    fake_setup(monkeypatch)
    output = tmp_path / "parent-owned.json"
    sidecars = {
        output.with_suffix(".wall.json"): b"owned wall",
        output.with_suffix(".log"): b"owned log",
    }
    for path, data in sidecars.items():
        path.write_bytes(data)
    assert study.study(tmp_path, output)
    assert all(path.read_bytes() == data for path, data in sidecars.items())


@pytest.mark.parametrize(
    "suffix", [".json", ".unknown", ".tensors.safetensors", ".sources-executed.json"]
)
def test_existing_experiment_family_fails_before_admission(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path, suffix: str
) -> None:
    output = tmp_path / "preserved.json"
    existing = output.with_suffix(suffix)
    existing.write_bytes(b"preserve exact prior bytes")

    def unexpected() -> list[dict[str, object]]:
        raise AssertionError("No admission or weights before collision guard")

    monkeypatch.setattr(study, "input_vectors", unexpected)
    with pytest.raises(FileExistsError):
        study.study(tmp_path, output)
    assert existing.read_bytes() == b"preserve exact prior bytes"

"""The maintained tokenizer policy and exact segmented Kai request encoding."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import NamedTuple, Protocol, cast

from wyat.core import Request
from wyat.wire import read_object

from .artifact import KaiArtifact, positive_integer

SUFFIX = (
    "\n\nSelect the single option best supported by the context and instructions."
    "\nDecision:"
)


class EncodedRequest(NamedTuple):
    ids: tuple[int, ...]
    candidate_positions: tuple[int, ...]
    query_position: int


class TokenizerProtocol(Protocol):
    @property
    def pad_token_id(self) -> int | None: ...

    @property
    def eos_token_id(self) -> int | None: ...

    def encode(self, text: str, *, add_special_tokens: bool = False) -> list[int]: ...


def load_tokenizer(root: Path) -> TokenizerProtocol:
    from transformers import AutoTokenizer

    config = read_object(root / "tokenizer_config.json")
    if config.get("fast_tokenizer_files"):
        raise ValueError(
            "Alternate tokenizer files require an explicit export contract"
        )
    # HF owns Qwen normalization, configured special tokens and legacy overrides.
    # Direct tokenizer.json loading silently skips those parts of the recipe.
    try:
        return cast(
            TokenizerProtocol,
            AutoTokenizer.from_pretrained(
                root,
                local_files_only=True,
                trust_remote_code=False,
            ),
        )
    except Exception as exc:
        raise ValueError(f"Cannot load local tokenizer: {exc}") from exc


class KaiEncoder:
    """Exact segmented tokens; cached values never contain contextual vectors."""

    def __init__(
        self,
        tokenizer: TokenizerProtocol,
        *,
        max_length: int,
        max_options: int,
        token_cache_size: int = 0,
    ) -> None:
        self.max_length = positive_integer(max_length, "max_length")
        if type(token_cache_size) is not int or token_cache_size < 0:
            raise ValueError("token_cache_size must be a nonnegative integer")
        self.tokenizer = tokenizer
        self.max_options = max_options
        self._option_tokens = lru_cache(maxsize=token_cache_size)(self._tokens)
        self._suffix = self._tokens(SUFFIX)
        pad_id = tokenizer.pad_token_id
        if pad_id is None:
            pad_id = tokenizer.eos_token_id
        if pad_id is None:
            raise ValueError("Tokenizer requires a pad or EOS token")
        self.pad_id = pad_id

    @classmethod
    def from_artifact(
        cls, artifact: KaiArtifact, *, max_length: int, token_cache_size: int = 0
    ) -> KaiEncoder:
        return cls(
            load_tokenizer(artifact.root),
            max_length=max_length,
            max_options=artifact.max_options,
            token_cache_size=token_cache_size,
        )

    def _tokens(self, text: str) -> tuple[int, ...]:
        if len(text.encode("utf-8")) > self.max_length * 32:
            raise ValueError("Input segment exceeds tokenization byte limit")
        ids = tuple(self.tokenizer.encode(text, add_special_tokens=False))
        if not ids or len(ids) > self.max_length:
            raise ValueError(
                "Input segment is empty or exceeds max_length; no truncation"
            )
        return ids

    def encode_request(self, request: Request) -> EncodedRequest:
        if request.task != "choice":
            raise ValueError("Kai currently supports choice requests only")
        if not 2 <= len(request.candidates) <= self.max_options:
            raise ValueError(f"Kai requires 2..{self.max_options} candidates")
        prefix = (
            f"Context:\n{request.context}\n\n"
            f"Task type: choice\nQuestion:\n{request.query}\nOptions:"
        )
        ids = list(self._tokens(prefix))
        positions: list[int] = []
        for candidate in request.candidates:
            payload = json.dumps(
                {"key": candidate.id, "description": candidate.text},
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            ids.extend(self._option_tokens("\n<option>\n" + payload + "\n</option>"))
            positions.append(len(ids) - 1)
        ids.extend(self._suffix)
        if len(ids) > self.max_length:
            raise ValueError(
                f"{len(ids)} tokens exceeds max_length={self.max_length}; no truncation"
            )
        return EncodedRequest(tuple(ids), tuple(positions), len(ids) - 1)

"""Failure-inclusive evaluation of a declared choice scorer on supplied cases."""

from __future__ import annotations

import hashlib
import json
import math
import time
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass

from .core import Decision, Model, Request, request_from_dict


@dataclass(frozen=True, slots=True)
class EvaluationCase:
    id: str
    request: Request
    expected: tuple[str, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.id, str) or not self.id.strip():
            raise ValueError("case ID must be nonempty text")
        if not isinstance(self.request, Request):
            raise ValueError("case request must be a Request")
        if (
            not isinstance(self.expected, tuple)
            or not self.expected
            or any(not isinstance(label, str) or not label for label in self.expected)
            or len(set(self.expected)) != len(self.expected)
        ):
            raise ValueError("expected IDs must be a nonempty tuple of unique text IDs")
        candidates = {candidate.id for candidate in self.request.candidates}
        if not set(self.expected) <= candidates:
            raise ValueError("expected IDs must belong to the submitted candidates")


def case_from_dict(value: object) -> EvaluationCase:
    """Parse labels separately from the request sent to the model."""
    if not isinstance(value, Mapping) or set(value) != {"id", "request", "expected"}:
        raise ValueError("evaluation case requires exactly id, request and expected")
    identifier, expected = value["id"], value["expected"]
    if not isinstance(identifier, str) or not isinstance(expected, list):
        raise ValueError("case ID must be text and expected must be a list of IDs")
    if any(not isinstance(label, str) for label in expected):
        raise ValueError("expected IDs must be text")
    return EvaluationCase(
        identifier, request_from_dict(value["request"]), tuple(expected)
    )


@dataclass(frozen=True, slots=True)
class EvaluationRow:
    id: str
    expected: tuple[str, ...]
    status: str
    prediction: Decision | None
    correct: bool
    latency_ms: float
    error: str | None

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "expected": list(self.expected),
            "status": self.status,
            "prediction": None
            if self.prediction is None
            else self.prediction.to_dict(),
            "correct": self.correct,
            "latency_ms": self.latency_ms,
            "error": self.error,
        }


def percentile(values: Sequence[float], fraction: float) -> float:
    """Return a linearly interpolated percentile of finite measured values."""
    if not values or not math.isfinite(fraction) or not 0 <= fraction <= 1:
        raise ValueError("nonempty values and a percentile fraction in [0, 1] required")
    if any(not math.isfinite(value) or value < 0 for value in values):
        raise ValueError("latencies must be finite and nonnegative")
    ordered = sorted(values)
    position = fraction * (len(ordered) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (position - lower)


@dataclass(frozen=True, slots=True)
class EvaluationReport:
    model_id: str
    rows: tuple[EvaluationRow, ...]
    input_sha256: str

    @property
    def total(self) -> int:
        return len(self.rows)

    @property
    def successful(self) -> int:
        return sum(row.status == "ok" for row in self.rows)

    @property
    def correct(self) -> int:
        return sum(row.correct for row in self.rows)

    @property
    def failed(self) -> int:
        return self.total - self.successful

    @property
    def accuracy(self) -> float:
        return self.correct / self.total

    @property
    def coverage(self) -> float:
        return self.successful / self.total

    @property
    def latency_p50_ms(self) -> float:
        return percentile([row.latency_ms for row in self.rows], 0.50)

    @property
    def latency_p95_ms(self) -> float:
        return percentile([row.latency_ms for row in self.rows], 0.95)

    def to_dict(self) -> dict[str, object]:
        return {
            "schema_version": 1,
            "input_sha256": self.input_sha256,
            "model_id": self.model_id,
            "total": self.total,
            "successful": self.successful,
            "failed": self.failed,
            "correct": self.correct,
            "accuracy": self.accuracy,
            "coverage": self.coverage,
            "latency_p50_ms": self.latency_p50_ms,
            "latency_p95_ms": self.latency_p95_ms,
            "rows": [row.to_dict() for row in self.rows],
        }


def _input_digest(cases: tuple[EvaluationCase, ...]) -> str:
    cohort = [
        {
            "id": case.id,
            "request": {
                "query": case.request.query,
                "context": case.request.context,
                "task": case.request.task,
                "candidates": [
                    {"id": candidate.id, "text": candidate.text}
                    for candidate in case.request.candidates
                ],
            },
            "expected": list(case.expected),
        }
        for case in cases
    ]
    canonical = json.dumps(
        cohort,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def evaluate(model: Model, cases: Iterable[EvaluationCase]) -> EvaluationReport:
    """Validate the complete cohort, then retain every attempted prediction.

    Latency covers every model call, including failures. The sequence may mix
    cold and warm calls; its percentiles do not establish steady-state throughput.
    Labels affect only the cohort hash and scoring, never a model request.
    """
    cohort = tuple(cases)
    if not cohort or any(not isinstance(case, EvaluationCase) for case in cohort):
        raise ValueError(
            "evaluation requires a nonempty cohort of EvaluationCase values"
        )
    if len({case.id for case in cohort}) != len(cohort):
        raise ValueError("evaluation case IDs must be unique")
    input_sha256 = _input_digest(cohort)
    model_id = model.model_id
    rows: list[EvaluationRow] = []
    for case in cohort:
        start = time.perf_counter_ns()
        try:
            prediction = model.decide(case.request)
        except Exception as error:
            latency_ms = (time.perf_counter_ns() - start) / 1_000_000
            rows.append(
                EvaluationRow(
                    case.id,
                    case.expected,
                    "error",
                    None,
                    False,
                    latency_ms,
                    f"{type(error).__name__}: {error}",
                )
            )
        else:
            latency_ms = (time.perf_counter_ns() - start) / 1_000_000
            rows.append(
                EvaluationRow(
                    case.id,
                    case.expected,
                    "ok",
                    prediction,
                    prediction.selected in case.expected,
                    latency_ms,
                    None,
                )
            )
    return EvaluationReport(model_id, tuple(rows), input_sha256)

"""Strict JSON decoding shared by the CLI and HTTP boundary."""

import json
import math
from pathlib import Path
from typing import cast

type JsonValue = (
    None | bool | int | float | str | list[JsonValue] | dict[str, JsonValue]
)
type JsonObject = dict[str, JsonValue]


def _object(pairs: list[tuple[str, JsonValue]]) -> JsonObject:
    result: JsonObject = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON field: {key}")
        result[key] = value
    return result


def _constant(value: str) -> None:
    raise ValueError(f"nonfinite JSON number: {value}")


def _float(value: str) -> float:
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError("JSON number exceeds finite float range")
    return parsed


def decode_json(data: str | bytes) -> JsonValue:
    # json.loads is dynamically typed; the decoder only creates JSON values.
    return cast(
        JsonValue,
        json.loads(
            data,
            object_pairs_hook=_object,
            parse_constant=_constant,
            parse_float=_float,
        ),
    )


def read_object(path: Path) -> JsonObject:
    value = decode_json(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"Expected a JSON object: {path.name}")
    return value
